const COLOR_CSS=":host{color:var(--ink);background:transparent;--accent:var(--tabbit-card-primary);--accent-alt:var(--tabbit-card-secondary);--ink:var(--tabbit-card-foreground);--muted:var(--tabbit-card-muted);--paper:var(--tabbit-card-background);--on-accent:var(--tabbit-card-on-primary);--panel-paper:var(--tabbit-card-background);--button-paper:var(--tabbit-card-background);--line:color-mix(in srgb,var(--tabbit-card-foreground) 18%,transparent);--soft:color-mix(in srgb,var(--tabbit-card-primary) 12%,var(--tabbit-card-background));--danger:var(--tabbit-card-foreground);--design-accent:var(--accent);--design-accentAlt:var(--accent-alt);--design-ink:var(--ink);--design-muted:var(--muted);--design-surface:var(--paper);--design-panel:var(--panel-paper);--design-stroke:var(--line);--design-onAccent:var(--on-accent);}.card{background:transparent}.card:has(>.infra-panel)>:not(.infra-panel){visibility:hidden}";
const CSS=".card{box-sizing:border-box;width:100%;height:100%;min-width:0;min-height:0;display:flex;flex-direction:column;padding:8px;color:var(--ink);font-size:12px;line-height:1.35;overflow:hidden}\n.card *{box-sizing:border-box}\n.card button,.card input{font:inherit;color:inherit}\n.main{flex:1;min-height:0;min-width:0;display:flex;flex-direction:column;gap:6px}\n.pane{flex:1;min-height:0;min-width:0;display:flex;flex-direction:column;gap:5px}\n.sheet{flex:1;min-height:0;min-width:0;overflow:auto;color:var(--ink)}\n.scroll{flex:1;min-height:0;min-width:0;overflow:auto;overscroll-behavior:contain}\n\n.tabs{display:flex;flex:none;border-bottom:1px solid var(--line)}\n.tab{flex:1;min-width:0;padding:4px 0 5px;border:0;border-bottom:2px solid transparent;background:transparent;color:var(--muted);cursor:pointer;white-space:nowrap}\n.tab.on{color:var(--ink);font-weight:700;border-bottom-color:var(--accent)}\n\n.days{display:flex;flex:none;align-items:stretch;gap:2px}\n.nav{flex:none;width:16px;padding:0;border:0;background:transparent;color:var(--muted);cursor:pointer;font-size:16px;line-height:1}\n.dchip{position:relative;flex:1;min-width:0;display:flex;flex-direction:column;align-items:center;justify-content:center;gap:0;padding:2px 0 4px;border:1px solid transparent;border-radius:8px;background:transparent;color:var(--ink);cursor:pointer}\n.dchip .dw{font-size:10px;color:var(--muted)}\n.dchip .dn{font-weight:700;font-variant-numeric:tabular-nums}\n.dchip.today{border-color:var(--accent)}\n.dchip.past{opacity:.6}\n.dchip.on{background:var(--accent);color:var(--on-accent);border-color:var(--accent);opacity:1}\n.dchip.on .dw{color:var(--on-accent)}\n.dot{position:absolute;bottom:1px;left:50%;width:4px;height:4px;margin-left:-2px;border-radius:50%;background:currentColor}\n\n.tools{display:flex;flex:none;align-items:center;flex-wrap:wrap;gap:4px 6px}\n.wk{flex:1 1 auto;min-width:0;color:var(--muted);font-size:11px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}\n.btn{flex:none;padding:4px 10px;border:1px solid var(--line);border-radius:8px;background:var(--button-paper,var(--panel-paper));color:var(--ink);cursor:pointer;white-space:nowrap}\n.btn.sm{padding:3px 8px}\n.btn.primary{background:var(--accent);color:var(--on-accent);border-color:var(--accent)}\n.btn:disabled{opacity:.5;cursor:default}\n\n.hint,.msg,.hint2{flex:none;font-size:10.5px;line-height:1.35;color:var(--muted)}\n.msg{color:var(--ink);padding:4px 6px;border-left:3px solid var(--accent-alt);background:var(--soft);border-radius:4px;font-size:11px;overflow-wrap:anywhere}\n.hint2{padding:0 0 4px}\n\n.agenda,.avl{display:flex;flex-direction:column;gap:4px;min-width:0}\n.dh{margin-top:4px;font-size:11px;font-weight:700;color:var(--muted)}\n.row{display:flex;align-items:flex-start;gap:6px;min-width:0;padding:5px 6px;border:1px solid var(--line);border-left:3px solid var(--accent);border-radius:8px;background:var(--panel-paper)}\n.row.meet{border-left-color:var(--muted);background:repeating-linear-gradient(135deg,transparent 0 6px,var(--soft) 6px 8px)}\n.row.plan.ok{border-left-color:var(--accent-alt)}\n.row.task{border-left-color:var(--accent-alt)}\n.row.done .rtitle{text-decoration:line-through;color:var(--muted)}\n.cb{flex:none;width:15px;height:15px;margin:1px 0 0;accent-color:var(--accent)}\n.rmain{flex:1;min-width:0;display:flex;flex-direction:column;gap:1px;padding:0;border:0;background:transparent;text-align:left;cursor:pointer}\n.rt{display:flex;flex-wrap:wrap;align-items:center;gap:2px 5px;font-variant-numeric:tabular-nums;font-size:11px;color:var(--muted)}\n.rtitle{min-width:0;font-weight:600;overflow-wrap:anywhere;word-break:break-word}\n.tag{padding:0 5px;border:1px solid var(--line);border-radius:999px;font-size:10px;color:var(--muted);white-space:nowrap}\n.tag.ok{border-color:var(--accent-alt);color:var(--ink)}\n.tag.warn{border-style:dashed;border-color:var(--accent);color:var(--ink);font-weight:700}\n.empty{padding:10px 6px;color:var(--muted);text-align:center;font-size:11.5px;line-height:1.5}\n.short{padding:4px 6px;border:1px dashed var(--accent-alt);border-radius:6px;font-size:10.5px;color:var(--ink);overflow-wrap:anywhere}\n\n.arow{display:flex;flex-wrap:wrap;align-items:center;gap:3px 8px;padding:4px 6px;border:1px solid var(--line);border-radius:8px;background:var(--panel-paper)}\n.arow:not(.on){opacity:.75}\n.alab{display:flex;align-items:center;gap:5px;min-width:46px;font-weight:600}\n.alab input{width:15px;height:15px;margin:0;accent-color:var(--accent)}\n.tg{display:flex;align-items:center;gap:4px;flex:1 1 auto;min-width:0}\n.tg input{flex:1 1 0;min-width:0;max-width:96px;padding:2px 4px;border:1px solid var(--line);border-radius:6px;background:var(--paper);color:var(--ink)}\n.ahint{flex-basis:100%;font-size:10.5px;color:var(--ink);border-left:3px solid var(--accent);padding-left:5px}\n\n.dbody{display:flex;flex-direction:column;gap:4px;min-width:0;color:var(--ink)}\n.dline{display:flex;flex-wrap:wrap;gap:2px 8px;min-width:0}\n.dk{flex:none;min-width:56px;color:var(--muted)}\n.dv{flex:1 1 120px;min-width:0;overflow-wrap:anywhere}\n\n/* 3x3: \u6781\u7b80 */\n.card[data-size=\"3x3\"]{padding:6px;font-size:11px}\n.card[data-size=\"3x3\"] .main{gap:3px}\n.card[data-size=\"3x3\"] .pane{gap:3px}\n.card[data-size=\"3x3\"] .wk,.card[data-size=\"3x3\"] .scopebtn,.card[data-size=\"3x3\"] .hint{display:none}\n.card[data-size=\"3x3\"] .tools .btn{flex:1 1 0;padding:3px 4px}\n.card[data-size=\"3x3\"] .nav{width:12px}\n.card[data-size=\"3x3\"] .tab{padding:2px 0 3px}\n.card[data-size=\"3x3\"] .dchip{padding:1px 0 3px}\n.card[data-size=\"3x3\"] .dchip .dw{font-size:9px}\n.card[data-size=\"3x3\"] .row{padding:3px 5px}\n.card[data-size=\"3x3\"] .msg{font-size:10px;padding:3px 5px}\n.card[data-size=\"3x3\"] .taskbar-sum{display:none}\n\n/* 6x3: \u5de6\u4fa7\u7ad6\u6392\u6807\u7b7e\uff0c\u65e5\u671f\u6761\u6a2a\u6392\uff0c\u53ea\u770b\u5f53\u5929 */\n.card[data-size=\"6x3\"]{padding:7px}\n.card[data-size=\"6x3\"] .main{flex-direction:row;gap:8px}\n.card[data-size=\"6x3\"] .tabs{flex-direction:column;flex:none;width:44px;border-bottom:0;border-right:1px solid var(--line);gap:2px;padding-right:4px}\n.card[data-size=\"6x3\"] .tab{flex:1;border-bottom:0;border-right:2px solid transparent;margin-right:-5px;padding:0;text-align:center}\n.card[data-size=\"6x3\"] .tab.on{border-right-color:var(--accent)}\n.card[data-size=\"6x3\"] .scopebtn,.card[data-size=\"6x3\"] .hint{display:none}\n.card[data-size=\"6x3\"] .row{padding:3px 6px}\n\n/* 3x6: \u7a84\u800c\u9ad8\uff0c\u5de5\u5177\u6761\u6362\u884c */\n.card[data-size=\"3x6\"] .wk{flex-basis:100%}\n.card[data-size=\"3x6\"] .tools .btn{flex:1 1 auto}\n\n/* 6x6 */\n.card[data-size=\"6x6\"]{padding:12px;font-size:13px}\n.card[data-size=\"6x6\"] .main{gap:8px}\n.card[data-size=\"6x6\"] .pane{gap:7px}\n.card[data-size=\"6x6\"] .dchip{padding:4px 0 6px}\n.card[data-size=\"6x6\"] .dchip .dw{font-size:11px}\n.card[data-size=\"6x6\"] .row{padding:7px 9px}\n.card[data-size=\"6x6\"] .rt{font-size:12px}\n.card[data-size=\"6x6\"] .agenda{gap:6px}\n.card[data-size=\"6x6\"] .tg input{max-width:120px}\n.card[data-size=\"6x6\"] .hint,.card[data-size=\"6x6\"] .msg{font-size:12px}\n";
var WD=['一','二','三','四','五','六','日'];
function pad2(n){return (n<10?'0':'')+n;}
function toD(str){var p=String(str).split('-');return new Date(+p[0],(+p[1])-1,+p[2]);}
function fmtD(d){return d.getFullYear()+'-'+pad2(d.getMonth()+1)+'-'+pad2(d.getDate());}
function addD(str,k){var d=toD(str);d.setDate(d.getDate()+k);return fmtD(d);}
function weekStartOf(str,off){var d=toD(str);var k=(d.getDay()+6)%7;d.setDate(d.getDate()-k+off*7);return fmtD(d);}
function wdOf(str){return WD[(toD(str).getDay()+6)%7];}
function shortD(str){var d=toD(str);return (d.getMonth()+1)+'/'+d.getDate();}
function toMin(t){if(!t||!/^\d{1,2}:\d{2}$/.test(t))return NaN;var p=t.split(':');return (+p[0])*60+(+p[1]);}
function fmtMin(m){return pad2(Math.floor(m/60))+':'+pad2(m%60);}
function durText(m){m=Math.round(m);var h=Math.floor(m/60),r=m%60;if(!h)return r+'分钟';if(!r)return h+'小时';return h+'小时'+r+'分';}
function nowMin(){var d=new Date();return d.getHours()*60+d.getMinutes();}

function norm(s){
  s=s||{};
  var a=Array.isArray(s.avail)?s.avail:[];
  var avail=[];
  for(var i=0;i<7;i++){var x=a[i]||{};avail.push({on:!!x.on,start:x.start||'',end:x.end||''});}
  return Object.assign({},s,{
    tasks:Array.isArray(s.tasks)?s.tasks:[],
    meetings:Array.isArray(s.meetings)?s.meetings:[],
    avail:avail,
    plan:Array.isArray(s.plan)?s.plan:[],
    note:s.note||null
  });
}

function validRange(a,b){var x=toMin(a),y=toMin(b);return x===x&&y===y&&y>x;}

function busyOf(n,date){
  var b=[];
  n.meetings.forEach(function(m){if(m.date===date)b.push([toMin(m.start),toMin(m.end)]);});
  n.plan.forEach(function(p){if(p.date===date&&p.status==='confirmed')b.push([toMin(p.start),toMin(p.end)]);});
  return b.filter(function(x){return x[0]===x[0]&&x[1]===x[1]&&x[1]>x[0];}).sort(function(p,q){return p[0]-q[0];});
}

function freeWins(n,date,idx){
  var a=n.avail[idx];
  if(!a||!a.on||!validRange(a.start,a.end))return [];
  var lo=toMin(a.start),hi=toMin(a.end);
  var t=fmtD(new Date());
  if(date<t)return [];
  if(date===t)lo=Math.max(lo,Math.ceil(nowMin()/15)*15);
  if(hi-lo<15)return [];
  var wins=[[lo,hi]];
  busyOf(n,date).forEach(function(b){
    var out=[];
    wins.forEach(function(w){
      if(b[1]<=w[0]||b[0]>=w[1]){out.push(w);return;}
      if(b[0]>w[0])out.push([w[0],b[0]]);
      if(b[1]<w[1])out.push([b[1],w[1]]);
    });
    wins=out;
  });
  return wins.filter(function(w){return w[1]-w[0]>=15;});
}

function schedOf(n,taskId){
  var sum=0;
  n.plan.forEach(function(p){if(p.taskId===taskId){var d=toMin(p.end)-toMin(p.start);if(d>0)sum+=d;}});
  return sum;
}

function conflictOf(n,p){
  var s=toMin(p.start),e=toMin(p.end),out=[];
  n.meetings.forEach(function(m){if(m.date===p.date&&toMin(m.start)<e&&toMin(m.end)>s)out.push('与会议「'+m.title+'」重叠');});
  n.plan.forEach(function(q){if(q.id!==p.id&&q.date===p.date&&toMin(q.start)<e&&toMin(q.end)>s)out.push('与「'+q.title+'」重叠');});
  return out;
}

function schedule(n,ws,uid){
  var days=[];
  for(var i=0;i<7;i++)days.push(addD(ws,i));
  var keep=n.plan.filter(function(p){return !(p.status!=='confirmed'&&days.indexOf(p.date)>=0);});
  var base=Object.assign({},n,{plan:keep});
  var wins=days.map(function(d,i){return freeWins(base,d,i);});
  var tasks=base.tasks.filter(function(t){return !t.done&&Number(t.minutes)>0;}).sort(function(a,b){
    var da=a.deadline||'9999',db=b.deadline||'9999';
    if(da!==db)return da<db?-1:1;
    return Number(b.minutes)-Number(a.minutes);
  });
  var items=[];
  tasks.forEach(function(t){
    var left=Number(t.minutes)-schedOf(base,t.id);
    for(var di=0;di<7&&left>0;di++){
      if(t.deadline&&days[di]>t.deadline)break;
      var ws2=wins[di];
      for(var wi=0;wi<ws2.length&&left>0;wi++){
        var w=ws2[wi];
        var take=Math.min(left,120,w[1]-w[0]);
        if(take<Math.min(30,left))continue;
        items.push({id:uid(),taskId:t.id,title:t.title,date:days[di],start:fmtMin(w[0]),end:fmtMin(w[0]+take),status:'draft',selected:true});
        left-=take;
        w[0]+=take+10;
      }
    }
  });
  return {plan:keep.concat(items),count:items.length,note:{at:new Date().toISOString(),ws:ws,count:items.length}};
}


function mount(ctx){
  const {root,el,state,ui,update,commit,redraw,uid,day,size,editor,panel}=ctx;
  const n=norm(state);
  const today=day();
  const compact=size==='3x3';
  if(ui.off==null)ui.off=0;
  if(ui.tab==null)ui.tab=n.plan.length?'plan':'cal';
  if(!ui.scope)ui.scope=size==='6x6'?'week':'day';
  if(!ui.sc)ui.sc={};
  const scope=(size==='3x3'||size==='6x3')?'day':ui.scope;
  const ws=weekStartOf(today,ui.off);
  const days=[];
  for(let i=0;i<7;i++)days.push(addD(ws,i));
  if(!ui.sel||days.indexOf(ui.sel)<0)ui.sel=days.indexOf(today)>=0?today:days[0];
  const nu=(extra)=>Object.assign({tab:ui.tab,off:ui.off,sel:ui.sel,scope:ui.scope,sc:ui.sc,view:null,form:null,draft:null,detail:null,msg:null,okc:false},extra||{});
  const focusOf=(date)=>({off:Math.round((toD(weekStartOf(date,0))-toD(weekStartOf(today,0)))/(7*86400000)),sel:date});
  const goMain=()=>{ui.view=null;ui.form=null;ui.draft=null;ui.detail=null;redraw();};
  const say=(msg)=>{ui.msg=msg;redraw();};

  function openForm(kind,id){
    let d;
    if(kind==='task'){
      const t=id?n.tasks.find(x=>x.id===id):null;
      d=t?{title:t.title,minutes:String(t.minutes),deadline:t.deadline||''}:{title:'',minutes:'',deadline:''};
    }else if(kind==='meet'){
      const m=id?n.meetings.find(x=>x.id===id):null;
      d=m?{title:m.title,date:m.date,start:m.start,end:m.end}:{title:'',date:ui.sel,start:'',end:''};
    }else{
      const p=n.plan.find(x=>x.id===id);
      d={date:p.date,start:p.start,end:p.end};
    }
    ui.draft=d;ui.form={kind:kind,id:id||null};ui.view='form';ui.detail=null;redraw();
  }
  function openDetail(kind,id){ui.detail={kind:kind,id:id,del:false};ui.view='detail';redraw();}

  function formView(){
    const f=ui.form;
    if(f.kind==='task'){
      return editor({title:f.id?'修改待办':'添加待办',draft:ui.draft,submitLabel:'保存',onBack:goMain,
        fields:[
          {key:'title',label:'待办名称',required:true,placeholder:'例如：整理周报'},
          {key:'minutes',label:'预计用时（分钟）',type:'number',required:true,min:5,step:1,placeholder:'例如 90'},
          {key:'deadline',label:'最晚完成日期（可选）',type:'date'}
        ],
        onSave:(v)=>{
          const title=String(v.title||'').trim();
          const m=Math.round(Number(v.minutes));
          if(!title)return '请填写待办名称';
          if(!(m>=5))return '预计用时至少 5 分钟';
          const newId=uid();
          return commit((s)=>{
            const c=norm(s);
            let tasks,plan=c.plan;
            if(f.id){
              tasks=c.tasks.map(t=>t.id===f.id?Object.assign({},t,{title:title,minutes:m,deadline:v.deadline||''}):t);
              plan=c.plan.map(p=>p.taskId===f.id?Object.assign({},p,{title:title}):p);
            }else{
              tasks=c.tasks.concat([{id:newId,title:title,minutes:m,deadline:v.deadline||'',done:false}]);
            }
            return Object.assign({},c,{tasks:tasks,plan:plan});
          },nu({tab:'tasks'}));
        }});
    }
    if(f.kind==='meet'){
      return editor({title:f.id?'修改会议记录':'添加已有会议',draft:ui.draft,submitLabel:'保存',onBack:goMain,
        fields:[
          {key:'title',label:'会议名称',required:true},
          {key:'date',label:'日期',type:'date',required:true},
          {key:'start',label:'开始',type:'time',required:true},
          {key:'end',label:'结束',type:'time',required:true}
        ],
        onSave:(v)=>{
          const title=String(v.title||'').trim();
          if(!title)return '请填写会议名称';
          if(!v.date)return '请选择日期';
          if(!validRange(v.start,v.end))return '请填写开始和结束时间，结束要晚于开始';
          const newId=uid();
          return commit((s)=>{
            const c=norm(s);
            const rec={id:f.id||newId,title:title,date:v.date,start:v.start,end:v.end};
            const meetings=f.id?c.meetings.map(m=>m.id===f.id?rec:m):c.meetings.concat([rec]);
            return Object.assign({},c,{meetings:meetings});
          },nu(Object.assign({tab:'cal'},focusOf(v.date))));
        }});
    }
    const it=n.plan.find(p=>p.id===f.id);
    return editor({title:'修改安排：'+(it?it.title:''),draft:ui.draft,submitLabel:'保存',onBack:goMain,
      fields:[
        {key:'date',label:'日期',type:'date',required:true},
        {key:'start',label:'开始',type:'time',required:true},
        {key:'end',label:'结束',type:'time',required:true}
      ],
      onSave:(v)=>{
        if(!v.date)return '请选择日期';
        if(!validRange(v.start,v.end))return '请填写开始和结束时间，结束要晚于开始';
        return commit((s)=>{
          const c=norm(s);
          return Object.assign({},c,{plan:c.plan.map(p=>p.id===f.id?Object.assign({},p,{date:v.date,start:v.start,end:v.end,status:'draft',selected:true}):p)});
        },nu(Object.assign({tab:'plan'},focusOf(v.date))));
      }});
  }


  function patchState(fn,extra){return commit((s)=>fn(norm(s)),nu(extra));}
  function toggleDone(id){
    patchState((c)=>Object.assign({},c,{tasks:c.tasks.map(t=>t.id===id?Object.assign({},t,{done:!t.done}):t)}),{tab:'tasks'});
  }
  function delTask(id){
    patchState((c)=>Object.assign({},c,{
      tasks:c.tasks.filter(t=>t.id!==id),
      plan:c.plan.filter(p=>!(p.taskId===id&&p.status!=='confirmed'))
    }),{tab:'tasks'});
  }
  function delMeet(id){
    patchState((c)=>Object.assign({},c,{meetings:c.meetings.filter(m=>m.id!==id)}),{tab:'cal'});
  }
  function delItem(id){
    patchState((c)=>Object.assign({},c,{plan:c.plan.filter(p=>p.id!==id)}),{tab:'plan'});
  }
  function toggleSel(id){
    ui.okc=false;
    update((s)=>{
      const c=norm(s);
      return Object.assign({},c,{plan:c.plan.map(p=>p.id===id?Object.assign({},p,{selected:p.selected===false}):p)});
    });
  }
  function setAvail(i,patch){
    update((s)=>{
      const c=norm(s);
      return Object.assign({},c,{avail:c.avail.map((a,k)=>k===i?Object.assign({},a,patch):a)});
    });
  }
  function applyAvail(mode){
    const src=n.avail.find(a=>validRange(a.start,a.end));
    if(!src){say('先给任意一天填好开始和结束时间，再套用。');return;}
    update((s)=>{
      const c=norm(s);
      return Object.assign({},c,{avail:c.avail.map((a,i)=>(mode==='all'||i<5)?{on:true,start:src.start,end:src.end}:a)});
    });
  }

  function gen(){
    if(!n.tasks.some(t=>!t.done&&Number(t.minutes)>0)){say('还没有可排的待办，先到「待办」里添加。');return;}
    if(!n.avail.some(a=>a.on&&validRange(a.start,a.end))){say('还没有设置空闲时间，先到「空闲」里勾选日子并填写时间。');return;}
    const r=schedule(n,ws,uid);
